class Solution {
public:
    string findContestMatch(int n) {
        vector<string> teams;
        for (int i = 1; i <= n; ++i) {
            teams.push_back(to_string(i));
        }
        while (teams.size() > 1) {
            vector<string> next;
            int size = teams.size();
            for (int i = 0; i < size / 2; ++i) {
                next.push_back("(" + teams[i] + "," + teams[size - 1 - i] + ")");
            }
            teams.swap(next);
        }
        return teams.front();
    }
};
